export const LINES = [{"text":"This man just walked away from the world championship.","start":0,"end":3.142},{"text":"On purpose.","start":3.172,"end":4.147},{"text":"Japan, 1976. Final race.","start":4.177,"end":7.954},{"text":"He leads James Hunt by three points.","start":7.984,"end":10.329},{"text":"On lap two, he pulls in and climbs out.","start":10.359,"end":13.059},{"text":"To understand why, rewind eighty-four days.","start":13.089,"end":16.221},{"text":"Germany. The Nürburgring. The track drivers call the Green Hell.","start":16.251,"end":20.209},{"text":"Lap two. His car snaps into the barrier and bursts into flames.","start":20.239,"end":24.23},{"text":"Trapped in the fire until other drivers drag him out.","start":24.26,"end":27.592},{"text":"Burned. Lungs full of toxic smoke.","start":27.622,"end":30.033},{"text":"Doctors don't think he'll survive.","start":30.063,"end":32.162},{"text":"Forty-two days later, he's racing again.","start":32.192,"end":35.036},{"text":"Wounds still bleeding under his helmet. He finishes fourth.","start":35.066,"end":38.507},{"text":"Back to Japan.","start":38.537,"end":39.727},{"text":"The rain is so heavy, drivers can barely see.","start":39.757,"end":42.749},{"text":"He's already been through fire once.","start":42.779,"end":44.807},{"text":"So he parks, and walks away.","start":44.837,"end":46.801},{"text":"Hunt takes the title. By one point.","start":46.831,"end":49.317},{"text":"He said his life was worth more than a title.","start":49.347,"end":52.31},{"text":"The bravest thing he ever did wasn't coming back.","start":52.34,"end":55.367},{"text":"It was knowing when to stop.","start":55.397,"end":57.276},{"text":"That's why...","start":57.306,"end":58.203}];
